fn fibonacci(n: usize) -> Vec<i32> {
    let mut result = Vec::with_capacity(n);
    
    if n == 0 {
        return result;
    }
    
    result.push(0); // F(0) = 0
    
    if n == 1 {
        return result;
    }
    
    result.push(1); // F(1) = 1
    
    // Generate remaining Fibonacci numbers
    for i in 2..n {
        let next = result[i - 1] + result[i - 2];
        result.push(next);
    }
    
    result
}